output_text:
[
  {
    "id": "no_carts_in_single_file_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles, so agents must leave the cart outside before entering them.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_narrow_with_cart",
    "text": "Agents may not move from a wide aisle into a single-file aisle while still holding a cart.",
    "abstraction": {
      "state_properties": {
        "wideAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileAisle": {
          "pre": {
            "and": [
              "MOVE",
              "wideAisle"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "enterSingleFileAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "must_park_before_single_file",
    "text": "On arriving at a cart-parking mouth of a single-file aisle with a cart, the agent is obliged to park the cart before proceeding into the aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart",
              "singleFileMouth"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "hasCart",
          "singleFileMouth"
        ]
      },
      "discharge": "parkCart"
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "After parking a cart at the mouth of a single-file aisle, the agent must retrieve it before continuing shopping or exiting.",
    "abstraction": {
      "state_properties": {
        "singleFileMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart",
              "singleFileMouth"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              },
              "singleFileMouth"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "cart_required_for_wide_shelf_service",
    "text": "Shelf interactions in normal wide shopping aisles must be performed while the agent has a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "wideShelfServiceCell": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "wideShelfServiceCell",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_cartless_travel_in_wide_aisles",
    "text": "Except inside single-file shelf aisles and their parking mouths, agents should not travel through wide public aisles without their cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "singleFileMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "widePublicAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "not": "singleFileMouth"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          "widePublicAisle",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "one_way_wide_aisles_no_west",
    "text": "Wide public aisles follow a one-way circulation pattern in which westward movement is prohibited.",
    "abstraction": {
      "state_properties": {
        "widePublicAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "W",
          "widePublicAisle"
        ]
      }
    }
  },
  {
    "id": "exit_with_cart_from_exit_lane",
    "text": "Agents must leave only from the designated exit cell and must still have their cart when exiting.",
    "abstraction": {
      "state_properties": {
        "exitCell": "at(11,7)",
        "bottomExitLane": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                8
              ]
            }
          ]
        }
      },
      "events": {
        "properExit": {
          "pre": {
            "and": [
              "EXIT",
              "exitCell",
              "hasCart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "properExit"
          }
        ]
      }
    }
  }
]
